'use strict';
const KEY='design-client-studio-v1', phases=['Discovery','Scoping','Design review','Revisions','Handoff'];
const industries={
 'Food & hospitality':{names:['Juniper Table','Morrow Coffee','Sunday Kitchen'],audience:'local diners planning a visit on their phones',problem:'People cannot quickly find the menu, opening hours, or a way to book.',goal:'Help visitors confidently choose a visit and complete a reservation.',task:'Find a suitable menu option and book a table',constraint:'The owner updates the menu weekly and has limited time for content.',metric:'Reservation completion rate'},
 'Health & wellness':{names:['Stillwell Studio','Kindred Movement','Forma Wellness'],audience:'first-time visitors comparing classes and instructors',problem:'New visitors struggle to choose a suitable class and understand pricing.',goal:'Make the first booking feel clear, welcoming, and low pressure.',task:'Choose an appropriate beginner class and book it',constraint:'Avoid medical claims; scheduling must fit an existing booking service.',metric:'First-class booking completion rate'},
 'SaaS & technology':{names:['Orbit Desk','Tandem Cloud','Relay Works'],audience:'small-team operations managers with little setup time',problem:'New users abandon setup before seeing useful information.',goal:'Help a new team reach its first useful result with less confusion.',task:'Create a workspace and complete the first useful action',constraint:'Engineering can change the interface but cannot replace the data model.',metric:'Onboarding completion rate'},
 'Retail & ecommerce':{names:['Fieldwork Goods','Common Thread','Northline Supply'],audience:'mobile shoppers comparing sustainable everyday products',problem:'Shoppers hesitate because product details, sizing, and delivery are unclear.',goal:'Help shoppers make an informed purchase without avoidable surprises.',task:'Compare two products and complete a purchase',constraint:'Use the existing product catalog and checkout provider.',metric:'Product-to-checkout progression rate'},
 'Arts & nonprofit':{names:['Open House Arts','Common Ground','Brightside Collective'],audience:'local residents discovering events and ways to contribute',problem:'Visitors cannot distinguish events, volunteering, and donation options.',goal:'Help people find a relevant event and understand how to participate.',task:'Find an accessible event and register',constraint:'A volunteer team must be able to maintain the content.',metric:'Event registration completion rate'}
};
const types=['Business website','Landing page','Mobile app','SaaS dashboard','Ecommerce experience'];
let state={version:1,projects:[],active:null},view='client';
try{const s=JSON.parse(localStorage.getItem(KEY));if(validState(s))state=s;}catch(e){}
function validState(s){return s&&s.version===1&&Array.isArray(s.projects)&&s.projects.every(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&industries[p.industry]&&types.includes(p.type)&&Array.isArray(p.messages)&&Array.isArray(p.tasks)&&Array.isArray(p.decisions)&&Array.isArray(p.evidence)&&p.portfolio&&Array.isArray(p.mentor)&&Array.isArray(p.artifacts)&&Number.isInteger(p.phase)&&p.phase>=0&&p.phase<5);}
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pnow=()=>state.projects.find(p=>p.id===state.active)||state.projects[0];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#saved').textContent='Saved on this browser';}catch(e){$('#saved').textContent='Storage full — export a backup';toast('Could not save. Export a backup before closing.');}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);}
function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function sample(a){return a[Math.floor(Math.random()*a.length)];}
function createProject(config){const info=industries[config.industry];const small=config.scope==='Focused',large=config.scope==='Full experience';const count=small?3:large?10:6;const goals={ 'Business website':'a responsive website', 'Landing page':'a focused campaign landing page','Mobile app':'a mobile product experience','SaaS dashboard':'an operational dashboard','Ecommerce experience':'a shopping experience'};const p={id:uid(),...config,name:sample(info.names),client:sample(['Alex Morgan','Jamie Chen','Sam Rivera','Jordan Ellis']),role:'Founder & project lead',phase:0,created:new Date().toISOString(),budget:small?'$1,500–$3,000':large?'$7,000–$12,000':'$3,500–$6,000',timeline:small?'2 weeks':large?'8 weeks':'4 weeks',deliverables:`${count} key ${config.type==='Business website'||config.type==='Landing page'?'page layouts':'screens'}, a clickable primary flow, responsive behavior notes, and a handoff summary`,messages:[],decisions:[],mentor:[],artifacts:[],evidence:[],portfolio:{role:'Independent designer — self-directed practice',process:'',outcome:'',reflection:''},tasks:['Confirm audience and primary task','Agree deliverables and exclusions','Document the primary flow','Review and address client feedback','Prepare an honest case study'].map(text=>({text,done:false})),scopeAccepted:false,reviewCount:0,revisionCount:0};p.messages.push({role:'client',text:`Hi, I’m ${p.client}, the founder of ${p.name}. We need ${goals[p.type]}. ${info.problem} ${p.difficulty==='Easy'?'Our priority is simple: '+info.goal:'I have a few ideas, but I’d like you to help us work out what matters most.'} What would you like to know first?`,phase:0});state.projects.unshift(p);state.active=p.id;save();view='client';render();}
const navs=[['client','◌','Client room'],['generator','✳','Project generator'],['mentor','◇','Design mentor'],['portfolio','▤','Portfolio'],['projects','▦','My projects']];
function render(){const p=pnow();$('#nav').innerHTML=navs.map(([id,icon,label])=>`<button data-view="${id}" class="${view===id?'active':''}"><span class="ico">${icon}</span>${label}</button>`).join('');$('#crumb').textContent=navs.find(n=>n[0]===view)[2];$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});if(!p&&view!=='generator'&&view!=='projects'){view='generator';render();return;}const screens={client:clientScreen,generator:generatorScreen,mentor:mentorScreen,portfolio:portfolioScreen,projects:projectsScreen};$('#app').innerHTML=screens[view](p);bind(p);}
function heading(k,title,sub,button=''){return `<div class="topline"><div><div class="kicker">${k}</div><h1>${title}</h1><p class="muted" style="margin:7px 0">${sub}</p></div>${button}</div>`;}
function summary(p){return `<div class="panel"><div class="row spread"><h3>Project snapshot</h3><span class="badge">FICTIONAL</span></div>${[['Project type',p.type],['Industry',p.industry],['Client difficulty',p.difficulty],['Scope',p.scope],['Simulated budget',p.budget],['Simulated timeline',p.timeline]].map(([l,v])=>`<div class="stat"><span>${l}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="note"><strong>Your studio, your pace.</strong>This is a fictional engagement. Client responses follow scenario rules. No real business results are generated. Projects save in this browser; export a backup to move devices.</div>`;}
function clientScreen(p){const completed=p.tasks.filter(t=>t.done).length;return heading('THE PRACTICE IS THE WORK','Step into the client room.','Ask good questions. Make decisions. Build something considered.',`<button id="newProject">＋ New project</button>`)+`<div class="layout"><div><div class="briefhero"><span class="badge">${esc(p.type.toUpperCase())} · ${esc(p.difficulty.toUpperCase())}</span><h2>${esc(p.name)}</h2><p>${esc(industries[p.industry].problem)}</p><span class="tag" style="color:#d2e8ac">FICTIONAL CLIENT ENGAGEMENT</span></div><section class="panel"><div class="steps">${phases.map((x,i)=>`<button class="${i===p.phase?'active':''}" data-phase="${i}">${i+1}. ${x}</button>`).join('')}</div><div class="row spread"><div class="person"><div class="avatar">${p.client.split(' ').map(x=>x[0]).join('')}</div><div><strong>${esc(p.client)}</strong><p>${esc(p.role)} · ${esc(p.name)}</p></div></div><span class="badge">CLIENT MODE</span></div><div class="conversation" id="conversation">${p.messages.filter(m=>m.phase===p.phase).map(m=>`<div class="message ${m.role==='user'?'user':''}"><small>${m.role==='user'?'YOU':'SIMULATED CLIENT'}</small>${esc(m.text)}</div>`).join('')||'<p class="muted">Start the conversation for this stage.</p>'}</div><form id="chatForm"><div class="compose"><textarea id="chat" aria-label="Message to simulated client" placeholder="Ask about the project, explain a decision, or present your work…" required maxlength="6000"></textarea><button class="primary">Send ↗</button></div></form><div class="chips">${(p.phase===0?['Who is the audience?','What does success look like?','What are the constraints?']:p.phase===1?['Confirm the proposed scope','What is out of scope?']:p.phase===2?['Review my submitted work','What concerns do you have?']:p.phase===3?['Review the changes I made','Negotiate the extra request']:['What do you need for handoff?']).map(t=>`<button data-prompt="${esc(t)}">${esc(t)}</button>`).join('')}</div><p class="hint">Describe your work before requesting review. The client can respond to text and named links; this MVP cannot inspect images or open URLs. Use the stages above to practice in any order.</p></section><section class="panel"><h3>Work submitted for review</h3><p class="hint">Save a design URL and describe the screen, flow, and rationale. Reviews use your description.</p><form id="artifactForm"><div class="grid"><div><label for="artifactTitle">Artifact title</label><input id="artifactTitle" required maxlength="160" placeholder="Booking flow · v1"></div><div><label for="artifactUrl">Design link (optional)</label><input id="artifactUrl" type="url" placeholder="https://figma.com/…"></div><div class="full"><label for="artifactDesc">What should the client review?</label><textarea id="artifactDesc" required maxlength="6000" placeholder="Describe layout, key steps, content, states, and why you made these choices."></textarea></div></div><button>Save artifact</button></form><div class="filelist">${p.artifacts.map(a=>`<p><strong>${esc(a.title)}</strong>${safeURL(a.url)?` · <a target="_blank" rel="noopener noreferrer" href="${esc(a.url)}">Open design ↗</a>`:''}<br><span class="muted">${esc(a.desc)}</span></p>`).join('')}</div></section><section class="panel"><h3>Decisions & scope log</h3><form id="decisionForm" class="row"><input id="decision" style="flex:1" required maxlength="1000" placeholder="Record an agreed decision or an open question"><button>Add note</button></form>${p.decisions.map(d=>`<div class="list-item"><span>${esc(d)}</span></div>`).join('')}</section></div><div><div class="panel"><div class="row spread"><h3>Your progress</h3><span class="muted">${completed}/${p.tasks.length}</span></div><div class="progress"><i style="width:${completed/p.tasks.length*100}%"></i></div>${p.tasks.map((t,i)=>`<label class="list-item"><input type="checkbox" data-task="${i}" ${t.done?'checked':''}><span>${esc(t.text)}</span></label>`).join('')}<p class="hint">Track completion yourself. Stage changes don’t imply approval.</p></div>${summary(p)}</div></div>`;}
function generatorScreen(){return heading('A NEW CHALLENGE AWAITS','Find your next practice project.','A believable brief. A client with opinions. Room to grow.')+`<div class="layout"><section class="panel"><h2>Make it your kind of challenge.</h2><p class="muted">Choose your parameters. The client reveals the rest through discovery.</p><form id="generator"><div class="grid">${[['type','Project type',types],['industry','Industry',Object.keys(industries)],['difficulty','Client difficulty',['Easy','Intermediate','Difficult','Nightmare']],['scope','Project scope',['Focused','Standard','Full experience']]].map(([id,l,opts])=>`<div class="field"><label for="${id}">${l}</label><select id="${id}" name="${id}">${opts.map(o=>`<option ${o==='Intermediate'||o==='Standard'?'selected':''}>${o}</option>`).join('')}</select></div>`).join('')}</div><div class="note" id="difficultyNote"><strong>Choose how much friction to practice.</strong>Easy: clear priorities. Intermediate: limited resources. Difficult: competing stakeholders. Nightmare: pressure and scope creep, with room to negotiate.</div><p class="hint">Focused: 3 key screens or layouts · Standard: 6 · Full experience: 10. All include a prototype and handoff notes. Industry scenarios are adapted to the selected interface type during discovery.</p><button class="primary" style="margin-top:14px">Generate project ↗</button></form></section><div><div class="briefhero"><span class="badge">LEARN BY DOING</span><h2>A safe place for the tricky parts.</h2><p>Practice asking why, defending a decision, setting a boundary, and turning feedback into a better design.</p></div><div class="note"><strong>Four spaces. One project.</strong>Client room for role-play.<br>Mentor for independent critique.<br>Project log for decisions.<br>Portfolio for the story behind your work.</div></div></div>`;}
function mentorScreen(p){return heading('A FRESH PAIR OF EYES','Get a second perspective.','Step outside the role-play. Think through your design decisions.')+`<div class="layout"><section class="panel"><div class="row spread"><h2>Design mentor</h2><span class="badge">SEPARATE FROM CLIENT</span></div><p class="muted">Describe a design or paste a rationale. The mentor provides structured prompts based on what you write, without approving work for the client.</p><form id="mentorForm"><div class="field"><label for="mentorFocus">Critique focus</label><select id="mentorFocus"><option>UX & task flow</option><option>UI & hierarchy</option><option>Accessibility</option><option>Business & scope</option></select></div><div class="field"><label for="mentorText">Design description & your reasoning</label><textarea id="mentorText" required maxlength="8000" style="min-height:180px" placeholder="What is the user's goal? Describe the screens, interaction states, hierarchy, and tradeoffs. What are you unsure about?"></textarea></div><button class="primary">Request critique ↗</button></form><p class="hint">Text-based heuristic feedback, not a visual audit or accessibility certification.</p>${p.mentor.slice().reverse().map(m=>`<div class="critique"><span class="badge">${esc(m.focus)}</span><p><strong>Your description</strong><br>${esc(m.input)}</p>${esc(m.text)}</div>`).join('')}</section><div>${summary(p)}</div></div>`;}
function portfolioScreen(p){return heading('SHOW THE THINKING','Turn practice into a story.','Document your choices honestly, from the first question to the final iteration.')+`<div class="layout"><div><section class="panel"><h2>Case-study workspace</h2><div class="note"><strong>Fictional client. Real design practice.</strong>The case study always carries a disclosure. Simulated budgets and targets are context, never measured business impact.</div><form id="portfolioForm" style="margin-top:24px">${[['role','Your role'],['process','Process, decisions & iterations'],['outcome','Design output (what you actually made)'],['reflection','Reflection & next steps']].map(([id,l])=>`<div class="field"><label for="port-${id}">${l}</label><textarea id="port-${id}" name="${id}" maxlength="12000">${esc(p.portfolio[id])}</textarea></div>`).join('')}<button class="primary">Save case study</button></form></section><section class="panel"><h3>Evidence register</h3><p class="hint">Record observations from tests you actually ran. Every item is labeled self-reported, with method, sample, date, and source. Simulated client comments are not user research.</p><form id="evidenceForm"><div class="grid"><div class="field"><label for="evResult">Observed result</label><input id="evResult" required maxlength="1000" placeholder="4 of 5 participants completed the booking task"></div><div class="field"><label for="evMethod">Method & sample</label><input id="evMethod" required maxlength="1000" placeholder="Moderated prototype test, 5 volunteers"></div><div class="field"><label for="evDate">Test date</label><input id="evDate" type="date" required></div><div class="field"><label for="evSource">Evidence source / notes</label><input id="evSource" required maxlength="1500" placeholder="Session notes or a research document link"></div></div><button>Add self-reported evidence</button></form>${p.evidence.map((e,i)=>`<div class="list-item"><span><span class="badge">SELF-REPORTED OBSERVATION</span><br>${esc(e.result)}<br><small class="muted">${esc(e.method)} · ${esc(e.date)} · ${esc(e.source)}</small></span><button class="small" data-remove-evidence="${i}" aria-label="Remove evidence">Remove</button></div>`).join('')}</section><section class="panel"><div class="row spread"><h2>Case-study preview</h2><button id="exportCase">Export Markdown ↗</button></div><div class="case-preview">${esc(caseText(p))}</div></section></div><div>${summary(p)}</div></div>`;}
function caseText(p){const info=industries[p.industry];return `# ${p.name} — ${p.type}\n\nDISCLOSURE: Self-directed concept project for a fictional client. Client conversations, business constraints, budgets, and targets are simulated. No real client endorsement or business impact is claimed.\n\n## The challenge\n${info.problem}\n\n## Intended audience\n${info.audience}\n\n## My role\n${p.portfolio.role||'Not documented yet.'}\n\n## Scope & constraints (simulated)\n${p.deliverables}\nBudget: ${p.budget}. Timeline: ${p.timeline}.\n${info.constraint}\n\n## Success hypothesis — not an outcome\n${info.goal}\nMetric to investigate: ${info.metric}. No baseline or improvement is measured by this simulator.\n\n## Process & decisions\n${p.portfolio.process||'Not documented yet.'}\n${p.decisions.length?'\nProject log:\n'+p.decisions.map(d=>'- '+d).join('\n'):''}\n\n## Design output\n${p.portfolio.outcome||'No design output documented yet.'}\n${p.artifacts.map(a=>`- ${a.title}${safeURL(a.url)?' ('+a.url+')':''}: ${a.desc}`).join('\n')}\n\n## Evidence & outcomes\n${p.evidence.length?p.evidence.map(e=>`Self-reported observation: ${e.result}\nMethod & sample: ${e.method}\nDate: ${e.date}\nSource: ${e.source}`).join('\n\n'):'No measured outcomes recorded. Any proposed benefit remains a hypothesis.'}\n\n## Reflection & next steps\n${p.portfolio.reflection||'Not documented yet.'}\n\nClient approval in this simulation is practice feedback, not evidence of user success.`;}
function projectsScreen(){return heading('YOUR GROWING BODY OF WORK','Projects on your desk.','Pick up where you left off. Each project keeps its own history.',`<button id="newProject" class="primary">＋ New project</button>`)+`<div class="grid">${state.projects.map(p=>`<section class="panel projectcard"><div class="row spread"><span class="badge">${esc(phases[p.phase])}</span><span class="muted">${esc(p.difficulty)}</span></div><h3>${esc(p.name)}</h3><p class="muted">${esc(p.type)} · ${esc(p.industry)}</p><p>${esc(industries[p.industry].problem)}</p><div class="row spread"><button data-open="${esc(p.id)}">Open project ↗</button><span class="hint">${p.messages.length} messages · ${p.artifacts.length} artifacts</span></div></section>`).join('')||'<div class="panel empty"><h2>A blank canvas.</h2><p>Create a project to start your practice.</p></div>'}</div>`;}
function safeURL(u){try{return ['https:','http:'].includes(new URL(u).protocol);}catch(e){return false;}}
function clientReply(p,text){const t=text.toLowerCase(),info=industries[p.industry],hard=['Difficult','Nightmare'].includes(p.difficulty),extra=p.difficulty==='Nightmare';
if(/audience|users|customers|who.*for/.test(t))return `Our primary audience is ${info.audience}. ${p.type==='SaaS dashboard'?'For the dashboard, translate that into a staff workflow: triage related requests, inspect details, and take the next action.':p.type==='Landing page'?'The landing page should explain the offer and send people into the existing service for the main action.':p.type==='Mobile app'?'For the app, focus on repeat use and a simple first-run experience.':''} ${hard?'Our co-founder also wants to appeal to everyone. I need help choosing a priority.':'Please prioritize their main task before secondary content.'}`;
if(/success|metric|goal|conversion|research|analytics/.test(t))return `The business goal is: ${info.goal} We could track ${info.metric.toLowerCase()}, but I do not have verified baseline data. Treat this as a hypothesis. ${p.type==='SaaS dashboard'?'For the staff-facing dashboard, use task completion time and error rate instead.':''} We have not conducted user research; you would need to plan and run actual tests.`;
if(/budget|deadline|timeline|constraint|content/.test(t))return `Our planning envelope is ${p.budget} over ${p.timeline} (both simulated). ${info.constraint} ${extra?'I was hoping for an earlier launch, too. What could we cut to ship a smaller first version?':'Tell me early if that means reducing scope.'}`;
if(/out of scope|exclusion/.test(t))return 'Let’s exclude production development, full brand strategy, paid photography, and integrations beyond prototype behavior. An extra flow needs a change request with cost and timeline impact. Record the boundary in our decisions log.';
if(/negotiate|extra request|change request|scope creep/.test(t))return `That is fair. ${hard?'The additional stakeholder request can move to phase two if you explain what we gain by protecting the core flow.':'Let’s keep the extra request in a later phase.'} Please record the agreed change and the impact on timeline. I won’t assume extra work is included.`;
if(p.phase===0)return `The issue we keep hearing is: “${info.problem}” ${hard?'Our team disagrees on whether to prioritize appearance or usability.':'I want visitors to feel confident about the next step.'} Ask me about our audience, success criteria, constraints, or move to scoping when you have enough context.`;
if(p.phase===1){if(/confirm|agree|proposal|deliverable|scope/.test(t)){p.scopeAccepted=true;const d=`Simulated scope agreement: ${p.deliverables} Budget ${p.budget}; timeline ${p.timeline}. Excludes production development, full branding, photography, and new integrations.`;if(!p.decisions.includes(d))p.decisions.push(d);return `We can use this as the baseline: ${p.deliverables} Within ${p.budget} and ${p.timeline}. This is a simulated agreement; any additional flows need a separate change request. ${hard?'Our marketing lead may still ask for more. Please help me keep us focused.':'Please start with the primary user journey.'}`;}return `Before I agree, can you outline the deliverables, exclusions, revision rounds, and what you need from me? My starting expectation is ${p.deliverables} What tradeoff would you recommend?`;}
if(p.phase===2||p.phase===3){if(!p.artifacts.length)return 'Please save an artifact below with a description of the flow and design rationale. I cannot inspect an image or open the link in this MVP, so I need your description before I can give a useful simulated review.';const a=p.artifacts[p.artifacts.length-1];if(p.phase===2){p.reviewCount++;return `Thanks for presenting “${a.title}”. Based only on your description: how easily can someone complete the main task, and what happens if something goes wrong? ${hard?'Our marketing lead wants a more prominent promotional message; I worry it competes with the main action. Can you show the tradeoff?':'I’d like the primary action and any next-step expectations to be unmistakable.'} ${extra?'Also, could we add a loyalty flow before launch? Please tell me whether that changes scope.':''} Please document what you will revise before we review again.`;}p.revisionCount++;if(p.revisionCount===1)return `For “${a.title}”, explain what changed and why. I need a clear before/after rationale, treatment of an error or empty state, and confirmation that the agreed scope still holds. Save the revised description as another artifact. Then explicitly ask for approval.`;if(/approv|sign.off|accept|ready/.test(t)&&p.artifacts.length>=2&&/changed|revis|updated|address|before|after/.test(t)){const d=`Simulated client sign-off for ${a.title}; based on designer description, not visual inspection or user testing.`;if(!p.decisions.includes(d))p.decisions.push(d);return `I’m comfortable giving simulated sign-off on “${a.title}” based on your stated revisions. Please package the prototype, design notes, and remaining questions for handoff. This approval is role-play feedback, not proof of usability or business results.`;}return 'Please save a second artifact describing your revisions, explain what changed in your message, and explicitly request approval. We should resolve open feedback and check scope before sign-off.';}
return `For handoff, I need the clickable prototype, layouts and component states, responsive behavior, content responsibilities, and a list of open questions. Include what has and has not been tested. ${p.scopeAccepted?'Keep the agreed exclusions visible.':'We have no recorded scope agreement yet; clarify that before calling this complete.'} Thank you for making the reasoning easy to follow.`;}
function mentorReply(focus,input,p){const map={ 'UX & task flow':['State the primary user task before defending the screen layout.','Trace the happy path and one recovery path. Name the point where the user must make the hardest decision.','Test whether someone can complete the task without hints; record completion and observed confusion.'], 'UI & hierarchy':['Make the visual order reflect the importance of the user’s decisions.','Compare the primary action, secondary actions, headings, and helper text. Describe relative prominence and spacing.','Check a narrow viewport and a long-content example. Confirm that the hierarchy survives both.'], 'Accessibility':['Describe keyboard order, visible focus, labels, and error announcements.','Measure actual foreground/background contrast; do not infer contrast from color names. Check target sizes and zoom behavior.','Test the prototype or implementation with keyboard and assistive technology where supported. No accessibility compliance conclusion is possible from this description.'], 'Business & scope':['Connect each deliverable to a business hypothesis and a user task.','Identify an exclusion and the impact of one requested addition on time and budget.','Draft a change request with a smaller alternative and a clear decision for the client.']};const flags=[];if(!/user|audience|customer|visitor|shopper/i.test(input))flags.push('The audience is not explicit in your description. Name who this serves.');if(!/because|reason|tradeoff|trade-off|so that/i.test(input))flags.push('Your rationale is not explicit. Explain why the choice fits the goal.');if(!/error|empty|loading|fail|recover/i.test(input))flags.push('Recovery and empty states are not described. Add at least one.');return `Review basis: your text only, not the linked artifact. These are heuristic prompts, not a scored assessment.\n\nWhat to investigate\n${(flags.length?flags:['Your description includes useful context. Validate the assumptions behind it.']).map(s=>'• '+s).join('\n')}\n\n${focus}\n${map[focus].map((s,i)=>`${i+1}. ${s}`).join('\n')}\n\nProject lens\n${industries[p.industry].goal}\n\nNext step\nChoose one recommendation, revise the artifact, and write what evidence would change your mind. Mentor advice does not change client approvals or project scope.`;}
function bind(p){$('#newProject')?.addEventListener('click',()=>{view='generator';render();});$('#generator')?.addEventListener('submit',e=>{e.preventDefault();createProject(Object.fromEntries(new FormData(e.target)));});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{state.active=b.dataset.open;save();view='client';render();});document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{p.phase=Number(b.dataset.phase);save();render();});document.querySelectorAll('[data-task]').forEach(b=>b.onchange=()=>{p.tasks[Number(b.dataset.task)].done=b.checked;save();render();});document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{$('#chat').value=b.dataset.prompt;$('#chat').focus();});$('#chatForm')?.addEventListener('submit',e=>{e.preventDefault();const text=$('#chat').value.trim();if(!text)return;p.messages.push({role:'user',text,phase:p.phase});p.messages.push({role:'client',text:clientReply(p,text),phase:p.phase});save();render();});$('#artifactForm')?.addEventListener('submit',e=>{e.preventDefault();const url=$('#artifactUrl').value.trim();if(url&&!safeURL(url)){toast('Use a valid http or https design link.');return;}p.artifacts.push({title:$('#artifactTitle').value.trim(),url,desc:$('#artifactDesc').value.trim()});save();render();toast('Artifact saved. Ask the client to review it.');});$('#decisionForm')?.addEventListener('submit',e=>{e.preventDefault();const text=$('#decision').value.trim();if(text)p.decisions.push(text);save();render();});$('#mentorForm')?.addEventListener('submit',e=>{e.preventDefault();const input=$('#mentorText').value.trim(),focus=$('#mentorFocus').value;if(!input)return;p.mentor.push({input,focus,text:mentorReply(focus,input,p)});save();render();});$('#portfolioForm')?.addEventListener('submit',e=>{e.preventDefault();p.portfolio=Object.fromEntries(new FormData(e.target));save();render();toast('Case study saved.');});$('#portfolioForm')?.addEventListener('input',e=>{if(e.target.name){p.portfolio[e.target.name]=e.target.value;save();}});$('#evidenceForm')?.addEventListener('submit',e=>{e.preventDefault();p.evidence.push({result:$('#evResult').value,method:$('#evMethod').value,date:$('#evDate').value,source:$('#evSource').value});save();render();});document.querySelectorAll('[data-remove-evidence]').forEach(b=>b.onclick=()=>{p.evidence.splice(Number(b.dataset.removeEvidence),1);save();render();});$('#exportCase')?.addEventListener('click',()=>download(p.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-case-study.md',caseText(p)));const conversation=$('#conversation');if(conversation)conversation.scrollTop=conversation.scrollHeight;}
$('#backup').onclick=()=>download('design-client-studio-backup.json',JSON.stringify(state,null,2),'application/json');
$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('Backup is too large.');const incoming=JSON.parse(await file.text());if(!validState(incoming))throw Error('This is not a supported Studio backup.');let count=0;for(const p of incoming.projects){const existing=state.projects.findIndex(x=>x.id===p.id);if(existing>=0){p.id=uid();p.name+=' (imported copy)';}state.projects.push(p);count++;}if(!state.active)state.active=state.projects[0]?.id;save();view='projects';render();toast(`Imported ${count} projects. Existing projects preserved.`);}catch(err){toast('Import failed: '+err.message);}e.target.value='';};
if(!state.projects.length)createProject({type:'Business website',industry:'Food & hospitality',difficulty:'Intermediate',scope:'Standard'});else render();
